from pilot_support import *
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=CHROMIUM,headless=True,args=['--no-sandbox']);page=b.new_page();page.goto(BASE)
 result=page.evaluate('''async()=>{const {makeProfile}=await import('./core.js'),{pilotPlan}=await import('./pilot.js'),{melodiesForPlan}=await import('./melodies.js'),{rewardFor}=await import('./reward-music.js'),{createAudioService}=await import('./services/audio-service.js');const profile=makeProfile('guitar6'),ctx=new AudioContext(),created=[],original=ctx.createBufferSource.bind(ctx);ctx.createBufferSource=()=>{const s=original(),start=s.start.bind(s);s.start=(when)=>{created.push({when,now:ctx.currentTime,buffer:s.buffer});start(when)};return s};const audio=createAudioService({getState:()=>({sound:true,voice:'guitar-clean',profile}),createContext:()=>ctx});const results=[];for(const m of melodiesForPlan(pilotPlan(profile)).values()){const r=rewardFor(m),offset=created.length;if(!await audio.playArrangement(r))throw Error('No playback '+m.id);const lead=r.events.filter(e=>e.velocity===1),played=created.slice(offset);if(played.length!==r.events.length)throw Error('Missing voices '+m.id);if(played.some(s=>s.when<s.now-.015))throw Error('Late note '+m.id);if(lead.some((e,i)=>played[i].buffer.duration+0.001<e.beats*r.step))throw Error('Cut sustain '+m.id);const first=played[0].buffer,samples=first.getChannelData(0),hz=440*2**((lead[0].midi-69)/12),period=Math.round(ctx.sampleRate/hz),count=Math.min(5000,samples.length-period-150),start=150;let xy=0,xx=0,yy=0;for(let i=start;i<start+count;i++){const x=samples[i],y=samples[i+period];xy+=x*y;xx+=x*x;yy+=y*y;}const correlation=xy/Math.sqrt(xx*yy);if(correlation<.85)throw Error('Pitch mismatch '+m.id+' '+correlation);results.push({id:m.id,firstMidi:lead[0].midi,correlation:Math.round(correlation*1000)/1000,scheduledVoices:played.length});audio.stopAudio();}await audio.dispose();return results}''')
 assert len(result)>=12
 print(json.dumps({'source_register_arrangements_scheduled':True,'no_late_notes':True,'held_buffers_long_enough':True,'first_note_waveform_matches_reference_register':True,'details':result}));b.close()
